"""ORD_LINE renumbering migration for Meridian CRM 4.2."""

from decimal import Decimal
from typing import Any


def _numeric_value(value: Any) -> Decimal:
    """Apply legacy numeric-context coercion: empty values compare as zero."""
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Return non-deleted ORD_LINE rows with contiguous per-order line numbers."""
    surviving: list[tuple[str, int, dict]] = []

    for original_index, row in enumerate(lines):
        if row.get("DEL_FLG", "") == "Y":
            continue
        surviving.append((str(row.get("ORD_ID", "")), original_index, row))

    by_order: dict[str, list[tuple[int, dict]]] = {}
    for order_id, original_index, row in surviving:
        by_order.setdefault(order_id, []).append((original_index, row))

    result: list[dict] = []
    for order_id in sorted(by_order):
        ordered_rows = sorted(
            by_order[order_id],
            key=lambda item: (_numeric_value(item[1].get("LINE_NO", "")), item[0]),
        )
        for new_line_no, (_, row) in enumerate(ordered_rows, start=1):
            copied_row = dict(row)
            copied_row["LINE_NO"] = new_line_no
            result.append(copied_row)

    return result
